(()=>{'use strict';
const M=window.CGY,KEY='cgy-shared-canvas-v2',$=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state,storageOK=true;try{state=JSON.parse(localStorage.getItem(KEY));}catch{storageOK=false;}if(![2,3].includes(state?.schema))state=M.seed();M.prepareCanvas(state);M.migrateAssets(state);
let savedRevision=state.revision,conflict=false,toastTimer,panelMode='',panelNode='',drag=null,busy=new Set(),creationPoint={x:100,y:100},creationSources=[],outlineOpen=innerWidth>800,query='',kindFilter='',platformFilter='',statusFilter='',heights={};
let lastCreatedNode=null,saveFlashAt=0;
const icons={calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M16 3v4M8 3v4M3 11h18"/>',topic:'<path d="M21 11.5a8.4 8.4 0 0 1-.9 3.8 8.5 8.5 0 0 1-7.6 4.7 8.4 8.4 0 0 1-3.8-.9L3 21l1.9-5.7a8.4 8.4 0 0 1-.9-3.8 8.5 8.5 0 0 1 4.7-7.6 8.4 8.4 0 0 1 3.8-.9h.5a8.5 8.5 0 0 1 8 8v.5Z"/>',file:'<path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8Z"/><path d="M14 2v6h6M8 13h8M8 17h6"/>',image:'<rect x="3" y="3" width="18" height="18" rx="2"/><circle cx="8.5" cy="8.5" r="1.5"/><path d="m21 15-5-5L5 21"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',minus:'<path d="M5 12h14"/>',plus:'<path d="M12 5v14M5 12h14"/>',left:'<path d="m14 6-6 6 6 6"/>',right:'<path d="m10 6 6 6-6 6"/>',up:'<path d="m6 14 6-6 6 6"/>',down:'<path d="m6 10 6 6 6-6"/>'};
const icon=name=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.file}</svg>`;
const btn=(label,action,attrs='',cls='')=>`<button type="button" data-action="${action}" class="${cls}" ${attrs}>${label}</button>`;
const field=(label,name,value,type='text',extra='')=>`<label class="field">${esc(label)}<input type="${type}" name="${name}" value="${esc(value)}" ${extra}></label>`;
const area=(label,name,value,extra='')=>`<label class="field">${esc(label)}<textarea name="${name}" ${extra}>${esc(value)}</textarea></label>`;
const badge=(text,cls='')=>`<span class="badge ${cls}">${esc(text)}</span>`;
function coverSvg(n){const v=n.image,photo=state.assets[v.photo]||'',format=n.platform||n.format||'xhs',w=format==='xhs'?720:1000,h=format==='xhs'?960:560;const lines=Array.from(v.title.match(/.{1,10}/gu)||['活动招募']).slice(0,4),x=v.layout==='center'?w/2:55,anchor=v.layout==='center'?'middle':'start';return `<svg xmlns="http://www.w3.org/2000/svg" width="${w}" height="${h}" viewBox="0 0 ${w} ${h}"><rect width="${w}" height="${h}" fill="${esc(v.background)}"/>${photo?`<image href="${esc(photo)}" x="0" y="0" width="${w}" height="${h}" preserveAspectRatio="xMidYMid slice"/><rect width="${w}" height="${h}" fill="white" opacity=".78"/>`:''}<text x="55" y="62" font-family="sans-serif" font-size="25" font-weight="700" fill="${v.ink}">C公益 / 职业探索</text><path d="M55 88H${w-55}" stroke="${v.ink}" opacity=".3"/>${lines.map((s,i)=>`<text x="${x}" y="${175+i*v.fontSize*1.5}" text-anchor="${anchor}" fill="${v.ink}" font-family="sans-serif" font-weight="700" font-size="${v.fontSize*1.4}">${esc(s)}</text>`).join('')}<text x="55" y="${h-145}" font-family="sans-serif" font-size="24" fill="${v.ink}">${esc(v.date.slice(0,28))}</text><text x="55" y="${h-101}" font-family="sans-serif" font-size="23" fill="${v.ink}">${esc(v.place.slice(0,26))}</text><text x="55" y="${h-42}" font-family="sans-serif" font-size="18" fill="${v.ink}">招募图文 · 演示排版 ${v.round} · 非现场照片</text></svg>`;}
const imageUrl=n=>'data:image/svg+xml;charset=utf-8,'+encodeURIComponent(coverSvg(n));
function toast(text){$('#status').textContent=text;$('#status').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#status').classList.remove('show'),5000);}
function flashSave(){const t=Date.now();if(t-saveFlashAt<600)return;saveFlashAt=t;const el=$('#save-state');if(!el)return;el.classList.remove('save-flash');void el.offsetWidth;el.classList.add('save-flash');}
function save(){if(conflict){savedLabel();return false;}try{const remote=JSON.parse(localStorage.getItem(KEY));if(remote?.revision>savedRevision){conflict=true;throw Error('另一窗口已有更新，请导出本页副本后载入最新数据。');}M.collectAssets(state);state.revision++;localStorage.setItem(KEY,JSON.stringify(state));savedRevision=state.revision;storageOK=true;savedLabel();flashSave();return true;}catch{storageOK=false;savedLabel();return false;}}
function savedLabel(){const e=$('#save-state');if(e)e.textContent=conflict?'窗口冲突 · 请保留本页副本':storageOK?'已自动保存至本机':'未保存至本机 · 请导出副本';const f=$('[data-editor-save]');if(f)f.textContent=storageOK&&!conflict?'修改已保存至本机':'本页修改未持久保存，请先导出副本';}
function transaction(label,fn){const previous=M.clone(state);try{M.remember(state,label);const result=fn();if(!save())throw Error('本机存储空间不足或存在窗口冲突，操作未应用；原内容仍保留。');return result;}catch(e){state=previous;throw e;}}
function nodeName(n){return n?.name||M.types[M.type(n)]||'内容';}
function header(){$('#header').innerHTML=`<div class="brand" aria-label="C公益">C</div><div class="project"><h1>${esc(state.project)}</h1><p>自由创作，共用资料 · 本地生成与协作演示</p></div><span class="saving" id="save-state"></span>${btn('撤销','undo',state.undo.length?'':'disabled')}${btn('示例成员','members','','plain')}${btn('演示说明','help','','plain')}`;savedLabel();}
function outline(){if(!$('#outline-search'))$('#outline').innerHTML=`<div class="row between"><h2>项目大纲</h2>${btn(icon('close'),'toggle-outline','aria-label="收起项目大纲"','icon plain')}</div><label class="field">按名称搜索<input id="outline-search" type="search" placeholder="搜索方案、稿件或素材"></label><div class="outline-filters"><label class="field">节点类型<select id="kind-filter"><option value="">全部类型</option>${[['schedule','排期'],['theme','活动主题'],['plan','活动方案'],['text','文字资料'],['image','图片素材'],['post','平台推文']].map(([v,l])=>`<option value="${v}">${l}</option>`).join('')}</select></label><label class="field">平台<select id="platform-filter"><option value="">全部平台</option><option value="wechat">公众号</option><option value="xhs">小红书</option></select></label><label class="field">稿件状态<select id="status-filter"><option value="">全部状态</option><option value="draft">草稿</option><option value="final">已定稿</option></select></label></div><p class="meta" id="outline-count"></p><div id="outline-groups"></div><div id="outline-results"></div>`;
const items=state.nodes.filter(n=>(!query||nodeName(n).toLowerCase().includes(query.toLowerCase()))&&(!kindFilter||n.kind===kindFilter)&&(!platformFilter||n.platform===platformFilter)&&(!statusFilter||(statusFilter==='final'?!!n.finalized:!n.finalized)));
$('#outline-groups').innerHTML=state.groups.map(g=>btn('分组 '+esc(g.name)+' · '+g.nodeIds.length+'项','group-panel',`data-group="${g.id}"`)).join('');$('#outline-count').textContent=`${items.length} / ${state.nodes.length} 项 · 勾选后可分组`;
$('#outline-results').innerHTML=items.map(n=>`<div class="outline-item ${state.selection.includes(n.id)?'active':''}"><input type="checkbox" class="node-select" data-id="${n.id}" aria-label="多选 ${esc(nodeName(n))}" ${state.selection.includes(n.id)?'checked':''}>${btn(`<strong>${esc(nodeName(n))}</strong><small>${M.types[M.type(n)]} · ${n.finalized?'已定稿':'草稿'}</small>`,'locate',`data-id="${n.id}"`,'plain')}</div>`).join('')||'<p class="meta">没有符合条件的节点，请调整搜索或筛选。</p>';}
function titleState(n){return badge(n.finalized?'已定稿':n.kind==='image'?'素材':n.kind==='post'?'草稿':n.confirmed?'已确认':n.adopted?.version===n.revision?'已采用':'共编中',n.finalized||n.confirmed?'ok':'');}
function nodeBody(n){if(n.kind==='schedule')return `<h3>${esc(n.data.title)}</h3><p>${esc(n.data.date)}</p><p>${esc(n.data.requirement)}</p><p class="meta">${esc(n.data.place)} · 计划 ${esc(n.data.count)} 人</p>`;if(n.kind==='theme')return `<h3>${esc(n.title)}</h3><p>${esc(n.direction)}</p>`;if(n.kind==='plan')return Object.entries({goal:'活动目标',audience:'受众',agenda:'活动安排',focus:'传播重点'}).map(([k,l])=>`<div class="plan-section"><strong>${l}</strong><p>${esc(n.content[k])}</p></div>`).join('');if(n.kind==='image')return `<h3>${esc(n.title)}</h3>${n.image.photo||n.poster?`<img class="material-preview" src="${n.poster?imageUrl(n):esc(state.assets[n.image.photo]||'')}" alt="${esc(n.body||n.title)}">`:'<div class="empty-image">上传一张项目图片<br>供多篇稿件复用</div>'}<p>${esc(n.body)}</p><p class="meta">${esc(n.image.source)} · ${n.image.usable?'使用状态已确认':'待核对使用状态'}</p>`;return `<h3>${esc(n.title)}</h3><div class="excerpt">${esc(n.body)}</div>`;}
function mainActions(n){if(n.kind==='theme')return btn('生成活动方案','generate-plan',`data-id="${n.id}"`);if(n.kind==='plan')return btn('生成公众号','generate-post',`data-id="${n.id}" data-platform="wechat"`)+btn('生成小红书','generate-post',`data-id="${n.id}" data-platform="xhs"`);if(n.kind==='post')return btn(n.finalized?'查看定稿':'确认定稿',n.finalized?'history':'finalize',`data-id="${n.id}"`);return btn('用于创作','derive',`data-id="${n.id}"`);}
function nodeHTML(n){const selected=state.selection.includes(n.id),changes=M.changedRefs(state,n);return `<article class="node ${selected?'selected':''} ${n.kind==='post'?'post '+n.platform:n.kind}" data-id="${n.id}" style="left:${n.x}px;top:${n.y}px" aria-label="${esc(nodeName(n))}"><div class="node-head"><input type="checkbox" class="node-select" data-id="${n.id}" aria-label="多选 ${esc(nodeName(n))}" ${selected?'checked':''}><div class="head-title" tabindex="0" role="button" aria-label="选择 ${esc(nodeName(n))}，方向键移动节点"><h2>${esc(nodeName(n))}</h2><span class="meta">${M.types[M.type(n)]}</span></div>${titleState(n)}</div><div class="node-foot">${btn('编辑内容','edit',`data-id="${n.id}"`,'edit-card')}${mainActions(n)}</div>${selected?`<div class="node-tools">${btn('来源 '+n.refs.length,'sources',`data-id="${n.id}"`)}${btn('评论 '+state.comments.filter(c=>c.nodeId===n.id).length,'comments',`data-id="${n.id}"`)}${btn('更多','more',`data-id="${n.id}"`)}</div>`:''}${changes.length?`<div class="notice">${changes.some(r=>r.missing||!M.get(state,r.id))?'引用的来源已删除':'来源已更新'} · 已采用内容保留 ${btn('处理引用','sources',`data-id="${n.id}"`)}</div>`:''}${n.kind==='post'?`<div class="cover"><img src="${imageUrl(n)}" alt="${esc(n.image.title)}，${esc(n.image.source)}"></div>`:''}<div class="node-body">${nodeBody(n)}<p class="meta">v${n.revision} ${n.finalized?'· '+esc(n.finalized.actor)+'定稿':''}</p></div></article>`;}
function hiddenGroup(id){return state.groups.find(g=>g.collapsed&&g.nodeIds.includes(id));}
function groupBounds(g){const nodes=g.nodeIds.map(id=>M.get(state,id)).filter(Boolean);if(!nodes.length)return {x:0,y:0,w:350,h:120};const x=Math.max(0,Math.min(...nodes.map(n=>n.x))-24),y=Math.max(0,Math.min(...nodes.map(n=>n.y))-64);return {x,y,w:g.collapsed?360:Math.max(...nodes.map(n=>n.x+(n.kind==='post'?420:370)))-x+24,h:g.collapsed?128:Math.max(...nodes.map(n=>n.y+(heights[n.id]||440)))-y+24};}
function groupsHTML(){return state.groups.map(g=>{const r=groupBounds(g);return `<section class="canvas-group ${g.collapsed?'collapsed':''}" data-group="${g.id}" style="left:${r.x}px;top:${r.y}px;width:${r.w}px;height:${r.h}px" aria-label="分组 ${esc(g.name)}"><div class="group-head"><div class="group-title" tabindex="0" role="button" aria-label="移动分组 ${esc(g.name)}">${esc(g.name)} <small>${g.nodeIds.length} 项</small></div>${btn(g.collapsed?'展开':'折叠','collapse-group',`data-group="${g.id}"`)}${btn('管理','group-panel',`data-group="${g.id}"`)}</div>${g.collapsed?`<p class="meta">${g.nodeIds.map(id=>esc(nodeName(M.get(state,id)))).join('、')}</p>`:''}</section>`;}).join('');}
function draw(){ $('#workspace').classList.toggle('outline-closed',!outlineOpen);$('#nodes').innerHTML=state.nodes.filter(n=>!hiddenGroup(n.id)).map(nodeHTML).join('');document.querySelectorAll('.node').forEach(el=>heights[el.dataset.id]=el.offsetHeight);$('#groups').innerHTML=groupsHTML();transform();connections();outline();$('#selection-bar').hidden=state.selection.length<2;$('#selection-bar').innerHTML=`<span>已选 ${state.selection.length} 项</span>${btn('创建分组','create-group','','primary')}${btn('取消多选','clear-selection')}`;$('#zoom').innerHTML=btn(icon('minus'),'zoom-out','aria-label="缩小画布"','icon')+`<span>${Math.round(state.view.zoom*100)}%</span>`+btn(icon('plus'),'zoom-in','aria-label="放大画布"','icon')+btn('回到全图','fit');const u=$('#header [data-action=undo]');if(u)u.disabled=!state.undo.length;}
function transform(){$('#canvas').scrollTop=0;$('#canvas').scrollLeft=0;$('#scene').style.transform=`translate(${state.view.x}px,${state.view.y}px) scale(${state.view.zoom})`;}
function endpoint(id){const g=hiddenGroup(id);return g?$(`[data-group="${g.id}"].canvas-group`):$(`.node[data-id="${id}"]`);}
function connections(){let html='<defs><marker id="arrow" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="5" markerHeight="5" orient="auto"><path d="M0 0 10 5 0 10Z" style="fill:#8b9ebc;stroke:none"/></marker></defs>';for(const n of state.nodes)for(const ref of n.refs){const a=endpoint(ref.id),b=endpoint(n.id);if(!a||!b||a===b)continue;const x=a.offsetLeft+a.offsetWidth,y=a.offsetTop+38,xx=b.offsetLeft,yy=b.offsetTop+38,d=Math.max(60,Math.abs(xx-x)/2);html+=`<path data-from="${ref.id}" data-to="${n.id}" pathLength="1" d="M${x} ${y} C${x+d} ${y},${xx-d} ${yy},${xx} ${yy}" marker-end="url(#arrow)"/>`;}$('#connections').innerHTML=html;const sel=state.selected;if(sel)$('#connections').querySelectorAll(`path[data-from="${sel}"],path[data-to="${sel}"]`).forEach(p=>p.classList.add('is-active'));if(lastCreatedNode){$('#connections').querySelectorAll(`path[data-from="${lastCreatedNode}"],path[data-to="${lastCreatedNode}"]`).forEach(p=>p.classList.add('line-in'));lastCreatedNode=null;}}
function pulseNode(id){const el=$(`.node[data-id="${id}"]`);if(!el)return;el.classList.remove('node-pop');void el.offsetWidth;el.classList.add('node-pop');setTimeout(()=>el.classList.remove('node-pop'),320);}
function select(id,add=false){state.selected=id;state.selection=add?(state.selection.includes(id)?state.selection.filter(v=>v!==id):[...state.selection,id]):[id];save();draw();pulseNode(id);}
function focusNode(id,edit=false){const n=M.get(state,id);if(!n)return;M.ensureVisible(state,id);state.selected=id;state.selection=[id];const c=$('#canvas'),width=n.kind==='post'?420:370;state.view.zoom=Math.min(1,Math.max(.7,(c.clientWidth-40)/width));state.view.x=Math.max(20,(c.clientWidth-width*state.view.zoom)/2)-n.x*state.view.zoom;state.view.y=24-n.y*state.view.zoom;if(innerWidth<=800)outlineOpen=false;save();draw();pulseNode(id);if(edit)openEditor(id);}
function fit(){const els=[...document.querySelectorAll('.node,.canvas-group')],c=$('#canvas');if(!els.length)return;const x=Math.min(...els.map(n=>n.offsetLeft)),y=Math.min(...els.map(n=>n.offsetTop)),xx=Math.max(...els.map(n=>n.offsetLeft+n.offsetWidth)),yy=Math.max(...els.map(n=>n.offsetTop+n.offsetHeight)),z=Math.max(.15,Math.min(1,(c.clientWidth-64)/(xx-x),(c.clientHeight-120)/(yy-y)));state.view={x:32-x*z,y:80-y*z,zoom:z};save();draw();}
function zoom(factor,cx=$('#canvas').clientWidth/2,cy=$('#canvas').clientHeight/2){const v=state.view,next=Math.max(.15,Math.min(1.6,v.zoom*factor)),r=next/v.zoom;v.x=cx-(cx-v.x)*r;v.y=cy-(cy-v.y)*r;v.zoom=next;save();transform();$('#zoom span').textContent=Math.round(next*100)+'%';}
function addMenu(point,sources=[]){creationPoint=point||{x:Math.max(20,(80-state.view.x)/state.view.zoom),y:Math.max(40,(100-state.view.y)/state.view.zoom)};creationSources=sources;const d=$('#chooser');d.innerHTML=`<header><h2 id="chooser-title">添加内容</h2>${btn(icon('close'),'close-chooser','aria-label="关闭添加菜单"','icon')}</header><p class="meta">${sources.length?'新内容将引用所选资料。':'在当前画布位置开始创作，之后可选择已有资料。'}</p>${[['活动筹备',['schedule','theme','plan']],['项目素材',['text','image']],['平台内容',['wechat','xhs']]].map(([label,ts])=>`<section><h3>${label}</h3><div class="create-options">${ts.map(t=>btn(`${icon(t==='image'?'image':t==='schedule'?'calendar':'file')}<span>${M.types[t]}</span>`,'create-node',`data-type="${t}" aria-label="新建 ${M.types[t]}"`)).join('')}</div></section>`).join('')}`;d.showModal();d.querySelector('[data-action=create-node]').focus();}
function editorFields(n){const name=field('节点名称','name',nodeName(n),'text','maxlength="100"');if(n.kind==='schedule')return name+field('排期名称','title',n.data.title)+field('活动时间','date',n.data.date)+field('地点','place',n.data.place)+area('任务要求','requirement',n.data.requirement)+field('参与对象','audience',n.data.audience)+field('计划人数','count',n.data.count,'number','min="0"')+field('报名入口','signup',n.data.signup)+field('排期来源','source',n.data.source);if(n.kind==='theme')return name+area('活动主题','title',n.title)+area('讨论方向','direction',n.direction);if(n.kind==='plan')return name+area('活动目标','content.goal',n.content.goal)+area('受众','content.audience',n.content.audience)+area('活动安排','content.agenda',n.content.agenda)+area('传播重点','content.focus',n.content.focus);if(n.kind==='text')return name+field('资料标题','title',n.title)+area('资料正文','body',n.body)+field('资料来源','source',n.source);const imageFields=`<h3>配图与关键信息</h3>${field('配图主标题','image.title',n.image.title)}${field('图片上的时间','image.date',n.image.date)}${field('图片上的地点','image.place',n.image.place)}<div class="field-grid">${field('背景颜色','image.background',n.image.background,'color')}${field('配图字号','image.fontSize',n.image.fontSize,'number','min="28" max="58"')}</div><label class="field">文字对齐<select name="image.layout"><option value="left" ${n.image.layout==='left'?'selected':''}>左对齐</option><option value="center" ${n.image.layout==='center'?'selected':''}>居中</option></select></label><label class="field">上传图片（PNG、JPG或WebP，最大2MB）<input type="file" id="photo-upload" accept="image/png,image/jpeg,image/webp"></label>${field('图片来源 / 使用依据','image.source',n.image.source)}<label class="check"><input type="checkbox" name="image.usable" ${n.image.usable?'checked':''}>已核对配图来源与使用状态</label>`;return name+(n.kind==='image'?field('素材标题','title',n.title)+area('人工画面说明','body',n.body):field('标题','title',n.title)+area('正文','body',n.body))+imageFields;}
function openEditor(id,fieldName){const n=M.get(state,id);if(!n)return;M.ensureVisible(state,id);state.selected=id;state.selection=[id];draw();const d=$('#editor');d.dataset.node=id;d.innerHTML=`<header><div><h2 id="editor-title">${esc(nodeName(n))} · 编辑</h2><p class="meta">我 · <span data-current-version>v${n.revision}</span> · 自动保存</p></div>${btn(icon('close'),'close-editor','aria-label="关闭编辑，返回原节点"','icon')}</header><div class="editor-body"><div class="editor-fields">${editorFields(n)}<p id="editor-error" class="error" role="alert"></p></div><aside class="editor-side">${n.image?`<img data-live-cover src="${n.kind==='image'&&!n.poster&&n.image.photo?state.assets[n.image.photo]:imageUrl(n)}" alt="当前配图预览">`:''}${n.kind==='post'?`<h3>独立修改每一项</h3><div class="actions">${btn('只重新生成标题','regenerate','data-part="title"')}${btn('只重新生成正文','regenerate','data-part="body"')}${btn('只重新生成配图','regenerate','data-part="image"')}${btn('配图存为项目素材','material',`data-id="${id}"`)}</div><p class="meta">标题与排版属于本篇稿件，重做配图不覆盖手改文案。</p>`:''}<h3>引用与讨论</h3><p class="meta">当前引用 ${n.refs.length} 份资料，修改上游只提示，不覆盖。</p>${btn('选择已有资料','editor-sources',`data-id="${id}"`)}${btn('评论此节点','editor-comments',`data-id="${id}"`)}<p class="meta" style="margin-top:20px">生成、@和多人协作为本地演示，没有真实模型或通知。</p></aside></div><footer class="editor-bottom"><span class="meta" data-editor-save></span><div class="actions">${btn('返回画布','close-editor')}${n.kind==='theme'?btn('确认主题','confirm-theme',`data-id="${id}"`,'primary'):n.kind==='plan'?btn('采用此版方案','adopt',`data-id="${id}"`,'primary'):n.kind==='post'?btn('确认定稿','finalize',`data-id="${id}"`,'primary'):''}</div></footer>`;if(!d.open)d.showModal();d.scrollTop=0;savedLabel();const f=d.querySelector(`[name="${fieldName||'name'}"]`);f?.focus({preventScroll:true});if(fieldName)f?.scrollIntoView({block:'center'});}
function closeEditor(){const id=$('#editor').dataset.node;$('#editor').close();draw();$(`.node[data-id="${id}"] .head-title`)?.focus({preventScroll:true});}
function ask(title,html,action,label='确认'){const d=$('#confirm');d.innerHTML=`<div class="confirm-body"><h2 id="confirm-title">${esc(title)}</h2>${html}<p class="error" id="confirm-error" role="alert"></p><div class="actions">${btn('取消','cancel-confirm')}${btn(label,'do-confirm','','primary')}</div></div>`;d.action=action;d.showModal();}
function error(e){const el=$('#confirm').open?$('#confirm-error'):$('#editor').open?$('#editor-error'):null;if(el)el.textContent=e.message;toast(e.message);}
function run(key,action){if(busy.has(key))return;busy.add(key);toast('正在生成（本地模板模拟）…');document.querySelectorAll(`[data-action^="generate"]`).forEach(b=>b.disabled=true);setTimeout(()=>{try{const n=transaction('生成内容',action);draw();if(n)focusNode(n.id,true);toast('已新增独立稿件，已有手改稿保留');}catch(e){error(e);}finally{busy.delete(key);draw();}},500);}
function panel(mode,id){panelMode=mode;panelNode=id;const p=$('#panel'),n=M.get(state,id);p.hidden=false;const close=btn(icon('close'),'close-panel','aria-label="关闭侧栏"','icon');let title='',html='';
if(mode==='help'||mode==='members'){title=mode==='help'?'本地演示说明':'平级共编';html=`<div class="stack"><p>所有成员都能新增、编辑、评论、生成和确认内容。本机统一以“我”记录。</p><p>单击“添加”或双击空白处新增；勾选节点后创建分组。拖动标题栏移动，方向键和移动按钮也可操作。</p><p class="notice">没有真实模型、多人在线同步、@通知或自动发布。状态仅保存在当前浏览器；不同入口不共享存储。</p>${btn('导出画布副本','export-state')}${btn('载入其他窗口最新数据','load-remote')}<p class="meta">新版本在原存储中迁移节点，保留旧稿、图片、评论与定稿快照。</p></div>`;}
else if(mode==='more'){title=nodeName(n)+' · 更多';html=`<form id="rename-form" class="stack">${field('节点名称','name',nodeName(n),'text','required maxlength="100"')}<button type="submit">保存名称</button></form><div class="stack section-gap">${btn('复制为独立草稿','duplicate',`data-id="${id}"`)}${btn('查看版本记录','history',`data-id="${id}"`)}${btn('删除节点','delete',`data-id="${id}"`)}<h3>移动节点</h3><div class="actions">${['left','up','down','right'].map(d=>btn(icon(d),'nudge',`data-id="${id}" data-direction="${d}" aria-label="向${{left:'左',right:'右',up:'上',down:'下'}[d]}移动节点"`,'icon')).join('')}</div></div>`;}
else if(mode==='history'){title=nodeName(n)+' · 版本';html=`<p class="meta">当前 v${n.revision}。确认和替换内容前的快照单独保留。</p><div class="history">${n.history.map(h=>`<details><summary>${esc(h.label)} · v${h.snapshot.revision}<br><small>${esc(h.actor)} · ${esc(h.at)}</small></summary><pre>${esc(JSON.stringify({标题:h.snapshot.title,正文:h.snapshot.body,方案:h.snapshot.content,配图:h.snapshot.image},null,2))}</pre></details>`).join('')||'<p>尚无历史快照。日常编辑自动保存。</p>'}</div>`;}
else if(mode==='sources'){title=nodeName(n)+' · 引用';html=`<p class="meta">选择已有资料自动建立连线。替换引用保留手改文案及封面排版；同步上游需明确选择。</p><div class="source-current">${n.refs.map(r=>{const src=M.get(state,r.id),changed=M.changedRefs(state,n).some(x=>x.id===r.id);return `<div class="source-record"><strong>${esc(src?.name||r.name)}</strong><span class="meta">已采用 v${r.version} ${!src?'· 来源已删除':changed?'· 来源已更新':''}</span><p class="meta">${esc(r.snapshot?.title||r.snapshot?.content?.goal||r.snapshot?.image?.source||'已保留采用时的资料快照')}</p>${src&&changed?btn('同步该来源','sync-source',`data-source="${r.id}" data-id="${id}"`):''}</div>`;}).join('')||'<p>尚未引用资料，可以从下面选择。</p>'}</div>${M.changedRefs(state,n).length?btn('保留现稿，沿用已采用内容','keep',`data-id="${id}"`):''}<form id="sources-form" class="stack section-gap"><h3>选择已有资料</h3>${state.nodes.filter(x=>x.id!==id).map(x=>`<label class="check source-option"><input name="source" type="checkbox" value="${x.id}" ${n.refs.some(r=>r.id===x.id)?'checked':''}><span>${esc(nodeName(x))}<small>${M.types[M.type(x)]} · v${x.revision}</small></span></label>`).join('')}<button type="submit" class="primary">应用引用选择</button><p class="meta">取消勾选即可解除引用，已采用内容仍保留。循环引用会被阻止。</p></form>`;}
else if(mode==='group'){const g=state.groups.find(g=>g.id===id);title='管理分组';html=`<form id="group-name-form" class="stack">${field('分组名称','name',g.name,'text','required maxlength="100"')}<button type="submit">保存分组名称</button></form><div class="stack section-gap"><p>${g.nodeIds.length} 项 · ${g.collapsed?'已折叠':'已展开'}</p>${btn(g.collapsed?'展开分组':'折叠分组','collapse-group',`data-group="${id}"`)}${btn('解除分组，保留内容','ungroup',`data-group="${id}"`)}<h3>整体移动</h3><div class="actions">${['left','up','down','right'].map(d=>btn(icon(d),'group-nudge',`data-group="${id}" data-direction="${d}" aria-label="向${{left:'左',right:'右',up:'上',down:'下'}[d]}移动分组"`,'icon')).join('')}</div></div>`;}
else{title='讨论 · '+nodeName(n);const cs=state.comments.filter(c=>c.nodeId===id);html=`<p class="meta">评论绑定本节点和具体字段，@仅本地记录。</p>${cs.map(c=>`<article class="comment"><strong>${esc(c.actor)}</strong> <small>v${c.version} · ${esc(c.at)}</small><blockquote>${esc(c.field)}</blockquote><p>${esc(c.text)}</p>${btn('定位到'+c.field,'comment-locate',`data-id="${id}" data-field="${esc(c.field)}"`)}</article>`).join('')||'<p class="section-gap">还没有评论。</p>'}<form id="comment-form" class="stack section-gap"><label class="field">评论位置<select name="field">${['整个节点','节点名称',...(n.kind==='post'?['标题','正文','配图']:n.kind==='plan'?['活动方案']:n.kind==='theme'?['活动主题','讨论方向']:n.kind==='image'?['配图']:['资料正文'])].map(f=>`<option>${f}</option>`).join('')}</select></label>${area('评论内容','text','','required placeholder="写下建议，输入 @ 提及同事"')}<div class="actions">${M.members.map(m=>btn('@'+m,'mention',`data-member="${m}"`,'plain')).join('')}</div><button type="submit" class="primary">发布本地评论</button></form>`;}
p.innerHTML=`<header><h2>${esc(title)}</h2>${close}</header>${html}`;}
function directions(d){return {left:[-40,0],right:[40,0],up:[0,-40],down:[0,40]}[d];}
function action(el){const a=el.dataset.action,id=el.dataset.id||state.selected,n=M.get(state,id);switch(a){
case'add':addMenu();break;case'close-chooser':$('#chooser').close();break;
case'create-node':{const v=transaction('新增节点',()=>M.createNode(state,el.dataset.type,creationPoint,creationSources));$('#chooser').close();lastCreatedNode=v.id;focusNode(v.id,true);break;}
case'derive':addMenu({x:n.x+440,y:n.y},[id]);break;
case'edit':focusNode(id,true);break;case'locate':focusNode(id,true);break;case'close-editor':closeEditor();break;
case'generate-plan':run('plan-'+id,()=>M.generatePlan(state,id));break;
case'generate-post':run('post-'+id,()=>M.generatePosts(state,[el.dataset.platform],id)[0]);break;
case'confirm-theme':transaction('确认主题',()=>M.confirmTheme(state,id));closeEditor();toast('已记录确认人和版本');break;
case'adopt':transaction('采用方案',()=>M.adoptPlan(state,id));closeEditor();toast('已采用当前方案');break;
case'finalize':transaction('确认定稿',()=>M.finalize(state,id));if($('#editor').open)closeEditor();draw();toast('我已确认定稿，指定版本已保留');break;
case'regenerate':{const target=$('#editor').dataset.node,part=el.dataset.part;const work=()=>run(target+'-'+part,()=>M.regenerate(state,target,part));if(part==='image')work();else ask('只重新生成'+(part==='title'?'标题':'正文')+'？','<p>原内容存入版本记录，其他手改项保持不变。</p>',()=>{$('#confirm').close();work();},'保留旧稿并生成');break;}
case'material':{const v=transaction('配图存为素材',()=>M.materialFromPost(state,id));closeEditor();focusNode(v.id,true);break;}
case'comments':panel('comments',id);break;case'sources':panel('sources',id);break;case'more':panel('more',id);break;case'history':panel('history',id);break;
case'editor-sources':closeEditor();panel('sources',id);break;case'editor-comments':closeEditor();panel('comments',id);break;
case'sync-source':ask('同步该来源？','<p>图片来源只更新图片与使用信息，保留本稿封面标题和排版。方案来源会重新生成文案；当前手改稿先存入版本记录。</p>',()=>{transaction('同步来源',()=>M.syncRef(state,id,el.dataset.source));$('#confirm').close();draw();panel('sources',id);},'保留旧稿并同步');break;
case'keep':transaction('沿用已采用内容',()=>M.keepRefs(state,id));draw();panel('sources',id);break;
case'duplicate':{const v=transaction('复制节点',()=>M.duplicate(state,id));$('#panel').hidden=true;focusNode(v.id,true);break;}
case'delete':{const affected=M.impact(state,id);ask('删除“'+nodeName(n)+'”？',`<p>引用它的内容：${affected.length?affected.map(x=>esc(nodeName(x))).join('、'):'无'}</p><p>稿件中已采用的文字和图片保持不变，来源将标为已删除。删除后可以撤销。</p>`,()=>{transaction('删除 '+nodeName(n),()=>M.deleteNode(state,id));$('#confirm').close();$('#panel').hidden=true;draw();toast('节点已删除；已采用内容保留，可撤销');},'删除节点');break;}
case'undo':{const before=M.clone(state);try{M.undo(state);if(!save())throw Error('撤销无法保存，请导出副本');}catch(e){state=before;throw e;}$('#panel').hidden=true;draw();toast('已撤销，节点与引用关系已恢复');break;}
case'clear-selection':state.selection=[];save();draw();break;
case'create-group':ask('创建画布分组',field('分组名称','groupName','招募传播','text','required maxlength="100"'),()=>{const name=$('#confirm [name=groupName]').value;transaction('创建分组',()=>M.createGroup(state,state.selection,name));$('#confirm').close();draw();toast('分组已创建，引用关系不变');},'创建分组');break;
case'collapse-group':{const g=state.groups.find(g=>g.id===el.dataset.group);transaction('折叠或展开分组',()=>g.collapsed=!g.collapsed);draw();if(panelMode==='group')panel('group',g.id);break;}
case'group-panel':panel('group',el.dataset.group);break;
case'ungroup':transaction('解除分组',()=>state.groups=state.groups.filter(g=>g.id!==el.dataset.group));$('#panel').hidden=true;draw();break;
case'group-nudge':{const [dx,dy]=directions(el.dataset.direction);transaction('移动分组',()=>M.moveGroup(state,el.dataset.group,dx,dy));draw();break;}
case'nudge':{const [dx,dy]=directions(el.dataset.direction);transaction('移动节点',()=>{n.x=Math.max(0,n.x+dx);n.y=Math.max(0,n.y+dy);});draw();break;}
case'comment-locate':focusNode(id);openEditor(id,{'节点名称':'name','标题':'title','正文':'body','配图':'image.title','活动方案':'content.goal','活动主题':'title','讨论方向':'direction','资料正文':'body'}[el.dataset.field]);break;
case'mention':{const t=$('#comment-form textarea');t.value+=(t.value?' ':'')+'@'+el.dataset.member+' ';t.focus();break;}
case'toggle-outline':outlineOpen=!outlineOpen;draw();break;case'close-panel':$('#panel').hidden=true;panelMode='';break;case'members':panel('members');break;case'help':panel('help');break;
case'zoom-in':zoom(1.2);break;case'zoom-out':zoom(1/1.2);break;case'fit':fit();break;case'cancel-confirm':$('#confirm').close();break;case'do-confirm':$('#confirm').action();break;
case'export-state':{const url=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='C公益-项目画布.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);toast('已导出当前画布副本');break;}
case'load-remote':ask('载入最新本机数据？','<p>请先导出需要保留的本页副本，载入后采用其他窗口保存的数据。</p>',()=>{const v=JSON.parse(localStorage.getItem(KEY));if(![2,3].includes(v?.schema))throw Error('没有有效数据');state=v;M.prepareCanvas(state);M.migrateAssets(state);savedRevision=state.revision;conflict=false;$('#confirm').close();header();draw();panel('help');},'载入最新');break;
}}
document.addEventListener('click',e=>{if(e.target.closest('.node-select'))return;const b=e.target.closest('[data-action]');if(b){try{action(b);}catch(err){error(err);}return;}const node=e.target.closest('.node');if(!node)return;if(e.target.closest('.node-head'))select(node.dataset.id,e.shiftKey);else openEditor(node.dataset.id);});
$('#outline').addEventListener('input',e=>{if(e.target.id==='outline-search'){query=e.target.value;outline();}});
$('#outline').addEventListener('change',e=>{if(e.target.id==='kind-filter')kindFilter=e.target.value;else if(e.target.id==='platform-filter')platformFilter=e.target.value;else if(e.target.id==='status-filter')statusFilter=e.target.value;else return;outline();});
document.addEventListener('change',e=>{if(e.target.matches('.node-select')){select(e.target.dataset.id,true);return;}});
$('#editor').addEventListener('input',e=>{const f=e.target;if(!f.name)return;if(f.name==='name'&&!f.value.trim()){ $('#editor-error').textContent='节点名称不能为空';return;}let value=f.type==='checkbox'?f.checked:f.type==='number'?Number(f.value):f.value;if(f.name==='image.fontSize'&&(value<28||value>58)){ $('#editor-error').textContent='配图字号为28至58';return;}$('#editor-error').textContent='';const id=$('#editor').dataset.node;M.update(state,id,f.name,value);save();draw();$('[data-current-version]').textContent='v'+M.get(state,id).revision;const img=$('[data-live-cover]');if(img){const n=M.get(state,id);img.src=n.kind==='image'&&!n.poster&&n.image.photo?state.assets[n.image.photo]:imageUrl(n);}});
$('#editor').addEventListener('change',e=>{if(e.target.id!=='photo-upload')return;const file=e.target.files[0];if(!file)return;if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>2*1024*1024){error(Error('请选择不超过2MB的PNG、JPG或WebP'));return;}const id=$('#editor').dataset.node,reader=new FileReader();reader.onload=()=>{const before=state;state=M.withPhoto(state,id,reader.result,'本机上传：'+file.name+'，请补充使用依据');if(!save()){state=before;openEditor(id);error(Error('图片未保存，原内容保留；请导出副本或释放本机存储空间'));return;}openEditor(id,'image.source');};reader.onerror=()=>error(Error('读取图片失败，原图保留'));reader.readAsDataURL(file);});
$('#panel').addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.target);try{if(e.target.id==='sources-form'){const ids=f.getAll('source');transaction('修改引用',()=>M.setRefs(state,panelNode,ids));draw();panel('sources',panelNode);toast('已更新引用，手改文案和封面排版保留');}else if(e.target.id==='rename-form'){if(!f.get('name').trim())throw Error('请填写名称');transaction('重命名节点',()=>M.update(state,panelNode,'name',f.get('name').trim()));draw();panel('more',panelNode);}else if(e.target.id==='group-name-form'){transaction('重命名分组',()=>state.groups.find(g=>g.id===panelNode).name=f.get('name').trim());draw();panel('group',panelNode);}else if(e.target.id==='comment-form'){M.comment(state,panelNode,f.get('field'),f.get('text'));save();draw();panel('comments',panelNode);toast('评论仅保存在本机，未发送通知');}}catch(err){error(err);}});
$('#canvas').addEventListener('dblclick',e=>{if(e.target.closest('.node,.canvas-group,button,input'))return;const r=$('#canvas').getBoundingClientRect();addMenu({x:Math.max(0,(e.clientX-r.left-state.view.x)/state.view.zoom),y:Math.max(0,(e.clientY-r.top-state.view.y)/state.view.zoom)});});
$('#canvas').addEventListener('pointerdown',e=>{if(busy.size||e.button!==0||e.target.closest('button,input,textarea,select,#canvas-tools,#zoom,#selection-bar'))return;const node=e.target.closest('.node'),head=e.target.closest('.node-head'),group=e.target.closest('.group-head');if(node&&!head)return;if(e.target.closest('.canvas-group')&&!group)return;const id=head?.closest('.node').dataset.id,gid=group?.closest('.canvas-group').dataset.group;drag={id,gid,startX:e.clientX,startY:e.clientY,view:M.clone(state.view),nodes:state.nodes.map(n=>({id:n.id,x:n.x,y:n.y})),moved:false,before:M.clone(state)};if(node)node.classList.add('is-dragging');const groupEl=group?.closest('.canvas-group');if(groupEl)groupEl.classList.add('is-dragging');if(!node&&!groupEl)$('#canvas').classList.add('is-panning');$('#canvas').setPointerCapture(e.pointerId);});
$('#canvas').addEventListener('pointermove',e=>{if(!drag)return;const dx=e.clientX-drag.startX,dy=e.clientY-drag.startY;if(Math.abs(dx)+Math.abs(dy)>4)drag.moved=true;if(!drag.moved)return;if(drag.id||drag.gid){const ids=drag.gid?state.groups.find(g=>g.id===drag.gid).nodeIds:state.selection.includes(drag.id)&&state.selection.length>1?state.selection:[drag.id];const originals=drag.nodes.filter(n=>ids.includes(n.id)),xx=Math.max(dx/state.view.zoom,-Math.min(...originals.map(n=>n.x))),yy=Math.max(dy/state.view.zoom,-Math.min(...originals.map(n=>n.y)));for(const start of originals){const n=M.get(state,start.id);n.x=start.x+xx;n.y=start.y+yy;const el=$(`.node[data-id="${n.id}"]`);if(el){el.style.left=n.x+'px';el.style.top=n.y+'px';}}$('#groups').innerHTML=groupsHTML();connections();}else{state.view.x=drag.view.x+dx;state.view.y=drag.view.y+dy;transform();}});
$('#canvas').addEventListener('pointerup',()=>{if(!drag)return;const d=drag;drag=null;$('#canvas').classList.remove('is-panning');document.querySelectorAll('.node.is-dragging,.canvas-group.is-dragging').forEach(el=>el.classList.remove('is-dragging'));if(d.moved&&(d.id||d.gid)){const positions=state.nodes.map(n=>({id:n.id,x:n.x,y:n.y}));state=d.before;try{transaction(d.gid?'移动分组':'移动节点',()=>{positions.forEach(v=>Object.assign(M.get(state,v.id),{x:v.x,y:v.y}));});}catch(err){error(err);}}else if(d.id&&!d.moved)select(d.id);else if(d.gid&&!d.moved)panel('group',d.gid);else save();draw();});$('#canvas').addEventListener('pointercancel',()=>{if(drag)state=drag.before;drag=null;$('#canvas').classList.remove('is-panning');document.querySelectorAll('.node.is-dragging,.canvas-group.is-dragging').forEach(el=>el.classList.remove('is-dragging'));draw();});
const reduceMotion=matchMedia('(prefers-reduced-motion: reduce)');
function relatedSet(id){const set=new Set([id]),self=M.get(state,id);for(const n of state.nodes){if(n.id===id)continue;if(n.refs.some(r=>r.id===id)||self?.refs.some(r=>r.id===n.id))set.add(n.id);}return set;}
function focusLinks(id){document.querySelectorAll('.node.link-focus').forEach(el=>el.classList.remove('link-focus'));$('#connections').querySelectorAll('path.is-hot').forEach(p=>p.classList.remove('is-hot'));document.querySelectorAll('.outline-item.is-linked').forEach(el=>el.classList.remove('is-linked'));if(!id)return;const set=relatedSet(id);set.forEach(x=>$(`.node[data-id="${x}"]`)?.classList.add('link-focus'));$('#connections').querySelectorAll('path').forEach(p=>{if(set.has(p.dataset.from)&&set.has(p.dataset.to))p.classList.add('is-hot');});document.querySelectorAll(`.outline-item button[data-id="${id}"]`).forEach(b=>b.closest('.outline-item').classList.add('is-linked'));}
$('#canvas').addEventListener('pointerover',e=>{const node=e.target.closest('.node');if(node&&!node.contains(e.relatedTarget))focusLinks(node.dataset.id);});
$('#canvas').addEventListener('pointerout',e=>{const node=e.target.closest('.node');if(node&&!node.contains(e.relatedTarget))focusLinks(null);});
$('#outline').addEventListener('pointerover',e=>{const b=e.target.closest('button[data-action="locate"]');if(b&&!b.contains(e.relatedTarget))focusLinks(b.dataset.id);});
$('#outline').addEventListener('pointerout',e=>{const b=e.target.closest('button[data-action="locate"]');if(b&&!b.contains(e.relatedTarget))focusLinks(null);});
document.addEventListener('pointerdown',e=>{const b=e.target.closest('button');if(!b||b.disabled||reduceMotion.matches)return;const r=b.getBoundingClientRect(),d=Math.max(r.width,r.height),s=document.createElement('span');s.className='ripple';s.style.width=s.style.height=d+'px';s.style.left=(e.clientX-r.left)+'px';s.style.top=(e.clientY-r.top)+'px';b.appendChild(s);s.addEventListener('animationend',()=>s.remove());});
$('#canvas').addEventListener('wheel',e=>{if(e.target.closest('#panel'))return;e.preventDefault();if(e.ctrlKey||e.metaKey){const r=$('#canvas').getBoundingClientRect();zoom(e.deltaY<0?1.08:1/1.08,e.clientX-r.left,e.clientY-r.top);}else{state.view.x-=e.deltaX;state.view.y-=e.deltaY;transform();save();}},{passive:false});
document.addEventListener('keydown',e=>{if(e.target.closest('input,textarea,select')||$('#editor').open||$('#confirm').open||$('#chooser').open)return;if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'){e.preventDefault();try{action({dataset:{action:'undo'}});}catch(err){error(err);}return;}if(e.key.toLowerCase()==='n'&&!e.ctrlKey&&!e.metaKey){e.preventDefault();addMenu();return;}const dirs={ArrowLeft:[-30,0],ArrowRight:[30,0],ArrowUp:[0,-30],ArrowDown:[0,30]},node=e.target.closest('.node');if(dirs[e.key]&&e.target.closest('#canvas')){e.preventDefault();const [dx,dy]=dirs[e.key];if(node){transaction('键盘移动节点',()=>{const n=M.get(state,node.dataset.id);n.x=Math.max(0,n.x+dx);n.y=Math.max(0,n.y+dy);});draw();$(`.node[data-id="${node.dataset.id}"] .head-title`)?.focus();}else{state.view.x-=dx;state.view.y-=dy;save();transform();}}if(['+','=','-','Home'].includes(e.key)&&e.target.closest('#canvas')){e.preventDefault();e.key==='Home'?fit():zoom(e.key==='-'?1/1.2:1.2);}if(node&&['Enter',' '].includes(e.key)&&e.target.matches('.head-title')){e.preventDefault();openEditor(node.dataset.id);}});
window.addEventListener('storage',e=>{if(e.key===KEY&&e.newValue&&JSON.parse(e.newValue).revision>savedRevision){conflict=true;savedLabel();toast('其他窗口已保存更新，导出副本后再载入最新数据。');}});
document.body.classList.add('booting');header();draw();if(!state.revision)save();setTimeout(()=>document.body.classList.remove('booting'),1100);
})();
